/**
 * @name Command injection via subprocess/os.system
 * @description Using subprocess or os.system with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        call = API::moduleImport("os").getMember("system").getACall() or
        call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection vulnerability: untrusted input flows to $@.", source.getNode(), "system command"

/**
 * @name Command Injection Vulnerability
 * @description Untrusted input flowing to command execution functions
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["run", "Popen", "call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection vulnerability: untrusted input flows to command execution from $@.", source.getNode(), "user input"

/**
 * @name SQL Injection in google-auth
 * @description SQL injection vulnerability from untrusted data to SQL execution
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection-auth
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SqlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("sqlite3").getMember(["execute", "executemany", "executescript"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SqlFlow = TaintTracking::Global<SqlConfig>;
import SqlFlow::PathGraph

from SqlFlow::PathNode source, SqlFlow::PathNode sink
where SqlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection vulnerability from $@.", source.getNode(), "user input"
